-- Brendi menu copy: retire the launch catalog and seed Salada Fit, combos, paid add-ons and drinks.
update public.products set active = false where id::text like '11111111-%';
on conflict (id) do update set name = excluded.name, slug = excluded.slug, category = excluded.category, price_cents = excluded.price_cents, image_path = excluded.image_path, description = excluded.description, sort_order = excluded.sort_order, active = true;
